-- GenDB engine variant Q14-wrapped_tables: template q14.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  100.00 * SUM(
    CASE
      WHEN p_type LIKE 'PROMO%'
      THEN l_extendedprice * (
        1 - l_discount
      )
      ELSE 0
    END
  ) / SUM(l_extendedprice * (
    1 - l_discount
  )) AS promo_revenue
FROM (
  SELECT
    *
  FROM lineitem
) AS lineitem, (
  SELECT
    *
  FROM part
) AS part
WHERE
  l_partkey = p_partkey
  AND l_shipdate >= $1
  AND l_shipdate < $1 + INTERVAL '1 MONTH'
